import { prisma } from "@/lib/prisma";import { mobileApiError,mobileJson,mobileOptions,requireMobileUser } from "@/lib/mobile-api";import { requestOrigin } from "@/lib/user-perks";import { serializeVideoLive } from "@/lib/video-live";import { emitToVideoLive } from "@/lib/realtime";
export function OPTIONS(){return mobileOptions()}
async function find(params){const{liveId}=await params;const row=await prisma.videoLiveSession.findUnique({where:{publicId:decodeURIComponent(liveId)},include:{host:true,guestRequests:{where:{status:"APPROVED"},include:{user:{select:{publicId:true,name:true,profileImage:true}}},orderBy:{slot:"asc"}}}});if(!row)throw Object.assign(new Error("Live video not found."),{code:"LIVE_NOT_FOUND"});return row}
export async function GET(request,{params}){try{await requireMobileUser(request);const row=await find(params);return mobileJson({success:true,data:{session:await serializeVideoLive(row,requestOrigin(request)),guests:row.guestRequests.map(g=>({requestId:g.id,slot:g.slot,user:g.user}))}})}catch(e){return mobileApiError(e,"LIVE_READ_FAILED")}}
export async function PATCH(request,{params}){try{const user=await requireMobileUser(request),row=await find(params);if(row.hostId!==user.id)throw Object.assign(new Error("Only the host can update this live."),{code:"LIVE_HOST_REQUIRED"});const body=await request.json(),data={revision:{increment:1}};if(Object.hasOwn(body,"hostAway"))data.hostAway=Boolean(body.hostAway);if(body?.title){const title=String(body.title).trim();if(title.length>120)throw Object.assign(new Error("Title is too long."),{code:"VALIDATION_ERROR"});data.title=title}const updated=await prisma.videoLiveSession.update({where:{id:row.id},data,include:{host:true}}),payload={success:true,data:{session:await serializeVideoLive(updated,requestOrigin(request))}};emitToVideoLive(row.publicId,"live-video:state",payload);return mobileJson(payload)}catch(e){return mobileApiError(e,"LIVE_UPDATE_FAILED")}}
export async function DELETE(request,{params}){try{const user=await requireMobileUser(request),row=await find(params);if(row.hostId!==user.id)throw Object.assign(new Error("Only the host can end this live."),{code:"LIVE_HOST_REQUIRED"});const updated=await prisma.videoLiveSession.update({where:{id:row.id},data:{status:"ENDED",endedAt:new Date(),viewerCount:0,revision:{increment:1}},include:{host:true}});await prisma.videoLiveViewer.updateMany({where:{sessionId:row.id,active:true},data:{active:false}});const payload={success:true,data:{session:await serializeVideoLive(updated,requestOrigin(request))}};emitToVideoLive(row.publicId,"live-video:ended",payload);return mobileJson(payload)}catch(e){return mobileApiError(e,"LIVE_END_FAILED")}}
